def transform(grid):
    bg = max(set(v for row in grid for v in row), key=sum(row.count(v) for row in grid for v in row))
    h, w = len(grid), len(grid[0])
    out = [[bg]*w for _ in range(h)]
    for r in range(h-1):
        for c in range(w):
            if grid[r][c] != bg:
                out[r+1][c] = grid[r][c]
    return out
